import React, { useState, useEffect } from "react";
import "./App.css";
import { config } from "../../../config/constants.js";
import { Link } from "react-router-dom";

import GymTonicLogo from "../../../buildassets/GymTonicLogo.png";

function rot13(s) {
  return s.replace(
    /[A-Z]/gi,
    (c) =>
      "NOPQRSTUVWXYZABCDEFGHIJKLMnopqrstuvwxyzabcdefghijklm"[
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz".indexOf(c)
      ]
  );
}

const Home = () => {
  const [message, setMessage] = useState("");
  const [someText, setSomeText] = useState("Sreenzragnf");
  const [answer, setAnswer] = useState(null);

  useEffect(() => {
    fetch(config.BASE_PATH + "/hello")
      .then((response) => response.text())
      .then((error) => {
        setMessage(error);
      });
  }, []);

  const onSubmit = (ev) => {
    ev.preventDefault();
    setAnswer(rot13(someText));
  };

  return (
    <div className="App">
      <header className="App-header">
        <img
          src="../../build/assets/GymTonicLogo.png"
          className="App-logo"
          alt="logo"
        />
        <h1 className="App-title">{message}</h1>
      </header>
      <div className="flex bg-red-400 border-4 border-blue-500 m-4 p-4">
        <p className="bg-yellow-400 ">Hi!</p>
      </div>
      <p className="App-intro">
        To get started, edit <code>src/App.js</code> and save to reload.
      </p>
      <p className="bg-yellow-400 ">
        <Link to="test">App route</Link>
      </p>
      <form action="" onSubmit={onSubmit}>
        <p className="bg-yellow-400 ">
          <label htmlFor="some-text">Input some text: </label>
          <input
            name="some-text"
            id="some-text"
            value={someText}
            onChange={(ev) => setSomeText(ev.currentTarget.value)}
          />
        </p>
        <button>Calculate</button>
      </form>
      {answer && (
        <p>
          The answer is: <strong>{answer}</strong>
        </p>
      )}
    </div>
  );
};

export default Home;
